package com.abhiai.abhiai_backend.controller;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.abhiai.abhiai_backend.dto.ai.SocialSearchResponse;import com.abhiai.abhiai_backend.security.JwtPrincipal;import com.abhiai.abhiai_backend.service.SocialContentRetrievalService;@RestController@RequestMapping("/api/v1/social-ai")public class SocialAiController{private final SocialContentRetrievalService s;public SocialAiController(SocialContentRetrievalService s){this.s=s;}@GetMapping("/search")public SocialSearchResponse search(@AuthenticationPrincipal JwtPrincipal p,@RequestParam String query){return s.retrieve(p.userId(),query);}}
